/**
 * Requester → Gateway → Peer: initiate negotiation.
 * chat_ids lists the chats the requester wants to sync; the peer responds with
 * ranges only for chats it actually has history for.
 */
export interface SyncHistoryRequest {
  requesterDeviceId: string;
  protocolVersion: string;
  chatIds: string[];
  /**
   * nacl.box public key (base64) generated by the requester for this sync
   * session. The responder seals each DBMessage.text with this key so the
   * gateway never sees plaintext. Included in every Fetch so the responder
   * has it stateless without storing session state from the Request.
   */
  requesterPubkey: string;
  /**
   * Challenge-response authentication: the requester sends 32 random bytes
   * (base64) and its nacl.box device pubkey (hex). The responder must seal
   * the challenge with nacl.box(challenge, nonce, requesterDevicePub,
   * responderDevicePriv) and return the result in SyncHistoryAccept.
   * This proves the responder knows the private key for responder_device_pub.
   */
  challenge: string;
  requesterDevicePub: string;
}

/**
 * Per-chat range descriptor: advertises what the responder owns.
 * count is informational (lets the requester estimate total work).
 */
export interface SyncChatRange {
  chatId: string;
  minTs: number;
  maxTs: number;
  count: number;
}

/**
 * Peer → Gateway → Requester: accept + range advertisement.
 * responder_device_id lets the requester address subsequent SyncHistoryFetch
 * messages to this specific peer (stateless gateway routing).
 * symKey sealed by the responder for the requester's registered device pubkey.
 * nacl.box(symKey, nonce, requesterDevicePub, ephemeralPrivkey).
 * Allows a first-access device to decrypt chat history without key rotation.
 */
export interface SyncSymKeyForChat {
  chatId: string;
  ciphertext: string;
  nonce: string;
  ephemeralPubkey: string;
}

export interface SyncHistoryAccept {
  requesterDeviceId: string;
  responderDeviceId: string;
  protocolVersion: string;
  ranges: SyncChatRange[];
  /**
   * Challenge response: nacl.box(challenge, nonce, requesterDevicePub,
   * responderDevicePriv). Proves the responder knows the private key for
   * responder_device_pub. Empty if the requester sent no challenge.
   */
  challengeResponse: string;
  challengeNonce: string;
  responderDevicePub: string;
  /**
   * Per-chat symKeys sealed for the requester's registered device pubkey.
   * Only populated when the responder has a decrypted symKey for the chat.
   */
  sealedSymKeys: SyncSymKeyForChat[];
}

/**
 * Peer → Gateway → Requester: reject (peer has no history, is busy, or
 * speaks an incompatible protocol version).
 */
export interface SyncHistoryReject {
  requesterDeviceId: string;
  reason: string;
}

/**
 * Requester → Gateway → Peer: request a specific message range for one chat.
 * from_ts is an exclusive lower bound (0 = from the beginning).
 * to_ts is an inclusive upper bound (0 = no upper bound).
 * limit caps the total messages returned; 0 = responder uses its own default.
 * The SyncManager sets these based on local cursor state — not the protocol.
 */
export interface SyncHistoryFetch {
  requesterDeviceId: string;
  targetDeviceId: string;
  chatId: string;
  fromTs: number;
  toTs: number;
  limit: number;
  /**
   * Same requester_pubkey from SyncHistoryRequest, repeated here so the
   * responder can seal text fields without tracking per-session state.
   */
  requesterPubkey: string;
}

/**
 * Protocol-level history entry. Storage-agnostic: no Dexie, IndexedDB, or
 * schema details leak into this message. The receiver maps it to its own
 * persistence format.
 */
export interface SyncHistoryEntry {
  msgId: string;
  chatId: string;
  sender: string;
  ts: number;
  ciphertext: string;
  nonce: string;
  replyToMsgId: string;
  edited: boolean;
  editedAt: number;
  removed: boolean;
  removedAt: number;
  /**
   * DBMessage.text sealed with nacl.box(text, nonce, requesterPubkey, responderEphemeralPrivkey).
   * sealed_text_nonce is the nacl.box nonce (distinct from the message nonce above).
   * The responder ephemeral pubkey is carried per-chunk in SyncHistoryChunk.
   */
  sealedText: string;
  sealedTextNonce: string;
  /** JSON-encoded DBMessage.reactions: Record<identityKey, { emoji: string; ts: number }> */
  reactionsJson: string;
}

/**
 * Peer → Gateway → Requester: one batch of entries for an in-progress fetch.
 * has_more signals whether more chunks follow before SyncHistoryDone.
 * last_ts carries the ts of the final entry in this chunk — used by the
 * SyncManager to update its per-chat cursor for recovery after reconnect.
 */
export interface SyncHistoryChunk {
  requesterDeviceId: string;
  chatId: string;
  entries: SyncHistoryEntry[];
  hasMore: boolean;
  lastTs: number;
  /**
   * Ephemeral nacl.box pubkey (base64) generated by the responder for this
   * fetch. All SyncHistoryEntry.sealed_text values in this chunk were sealed
   * with the corresponding secret key. One keypair per handleSyncFetch call.
   */
  responderEphemeralPubkey: string;
}

/**
 * Peer → Gateway → Requester: signals the end of the entry stream for one
 * SyncHistoryFetch. total_sent is the count of entries sent across all chunks.
 * has_more is true when the responder hit the fetch limit and there are more
 * messages beyond last_ts — the requester should re-fetch from the cursor.
 */
export interface SyncHistoryDone {
  requesterDeviceId: string;
  chatId: string;
  totalSent: number;
  hasMore: boolean;
}

function createBaseChainIdentity(): ChainIdentity {
  return { chainFamily: 0, address: "", networkId: undefined };
}

export const ChainIdentity: MessageFns<ChainIdentity> = {
  encode(message: ChainIdentity, writer: BinaryWriter = new BinaryWriter()): BinaryWriter {
    if (message.chainFamily !== 0) {
      writer.uint32(8).int32(message.chainFamily);
    }
    if (message.address !== "") {
      writer.uint32(18).string(message.address);
    }
    if (message.networkId !== undefined) {
      writer.uint32(26).string(message.networkId);
    }
    return writer;
  },

  decode(input: BinaryReader | Uint8Array, length?: number): ChainIdentity {
    const reader = input instanceof BinaryReader ? input : new BinaryReader(input);
    const end = length === undefined ? reader.len : reader.pos + length;
    const message = createBaseChainIdentity();
    while (reader.pos < end) {
      const tag = reader.uint32();
      switch (tag >>> 3) {
        case 1: {
          if (tag !== 8) {
            break;
          }

          message.chainFamily = reader.int32() as any;
          continue;
        }
        case 2: {
          if (tag !== 18) {
            break;
          }

          message.address = reader.string();
          continue;
        }
        case 3: {
          if (tag !== 26) {
            break;
          }

          message.networkId = reader.string();
          continue;
        }
      }
      if ((tag & 7) === 4 || tag === 0) {
        break;
      }
      reader.skip(tag & 7);
    }
    return message;
  },

  fromJSON(object: any): ChainIdentity {
    return {
      chainFamily: isSet(object.chainFamily)
        ? chainFamilyFromJSON(object.chainFamily)
        : isSet(object.chain_family)
        ? chainFamilyFromJSON(object.chain_family)
        : 0,
      address: isSet(object.address) ? globalThis.String(object.address) : "",
      networkId: isSet(object.networkId)
        ? globalThis.String(object.networkId)
        : isSet(object.network_id)
        ? globalThis.String(object.network_id)
        : undefined,
    };
  },

  toJSON(message: ChainIdentity): unknown {
    const obj: any = {};
    if (message.chainFamily !== 0) {
      obj.chainFamily = chainFamilyToJSON(message.chainFamily);
    }
    if (message.address !== "") {
      obj.address = message.address;
    }
    if (message.networkId !== undefined) {
      obj.networkId = message.networkId;
    }
    return obj;
  },

  create<I extends Exact<DeepPartial<ChainIdentity>, I>>(base?: I): ChainIdentity {
    return ChainIdentity.fromPartial(base ?? ({} as any));
  },
  fromPartial<I extends Exact<DeepPartial<ChainIdentity>, I>>(object: I): ChainIdentity {
    const message = createBaseChainIdentity();
    message.chainFamily = object.chainFamily ?? 0;
    message.address = object.address ?? "";
    message.networkId = object.networkId ?? undefined;
    return message;
  },
};

function createBaseAuthProof(): AuthProof {
  return { jwt: undefined, signedMessage: undefined, hpChallenge: undefined };
}

export const AuthProof: MessageFns<AuthProof> = {
  encode(message: AuthProof, writer: BinaryWriter = new BinaryWriter()): BinaryWriter {
    if (message.jwt !== undefined) {
      writer.uint32(10).string(message.jwt);
    }
    if (message.signedMessage !== undefined) {
      SignedMessageProof.encode(message.signedMessage, writer.uint32(18).fork()).join();
    }
    if (message.hpChallenge !== undefined) {
      writer.uint32(26).bytes(message.hpChallenge);
    }
    return writer;
  },

  decode(input: BinaryReader | Uint8Array, length?: number): AuthProof {
    const reader = input instanceof BinaryReader ? input : new BinaryReader(input);
    const end = length === undefined ? reader.len : reader.pos + length;
    const message = createBaseAuthProof();
    while (reader.pos < end) {
      const tag = reader.uint32();
      switch (tag >>> 3) {
        case 1: {
          if (tag !== 10) {
            break;
          }

          message.jwt = reader.string();
          continue;
        }
        case 2: {
          if (tag !== 18) {
            break;
          }

          message.signedMessage = SignedMessageProof.decode(reader, reader.uint32());
          continue;
        }
        case 3: {
          if (tag !== 26) {
            break;
          }

          message.hpChallenge = reader.bytes();
          continue;
        }
      }
      if ((tag & 7) === 4 || tag === 0) {
        break;
      }
      reader.skip(tag & 7);
    }
    return message;
  },

  fromJSON(object: any): AuthProof {
    return {
      jwt: isSet(object.jwt) ? globalThis.String(object.jwt) : undefined,
      signedMessage: isSet(object.signedMessage)
        ? SignedMessageProof.fromJSON(object.signedMessage)
        : isSet(object.signed_message)
        ? SignedMessageProof.fromJSON(object.signed_message)
        : undefined,
      hpChallenge: isSet(object.hpChallenge)
        ? bytesFromBase64(object.hpChallenge)
        : isSet(object.hp_challenge)
        ? bytesFromBase64(object.hp_challenge)
        : undefined,
    };
  },

  toJSON(message: AuthProof): unknown {
    const obj: any = {};
    if (message.jwt !== undefined) {
      obj.jwt = message.jwt;
    }
    if (message.signedMessage !== undefined) {
      obj.signedMessage = SignedMessageProof.toJSON(message.signedMessage);
    }
    if (message.hpChallenge !== undefined) {
      obj.hpChallenge = base64FromBytes(message.hpChallenge);
    }
    return obj;
  },

  create<I extends Exact<DeepPartial<AuthProof>, I>>(base?: I): AuthProof {
    return AuthProof.fromPartial(base ?? ({} as any));
  },
  fromPartial<I extends Exact<DeepPartial<AuthProof>, I>>(object: I): AuthProof {
    const message = createBaseAuthProof();
    message.jwt = object.jwt ?? undefined;
    message.signedMessage = (object.signedMessage !== undefined && object.signedMessage !== null)
      ? SignedMessageProof.fromPartial(object.signedMessage)
      : undefined;
    message.hpChallenge = object.hpChallenge ?? undefined;
    return message;
  },
};

function createBaseSignedMessageProof(): SignedMessageProof {
  return { publicKeyHex: "", signatureHex: "" };
}

export const SignedMessageProof: MessageFns<SignedMessageProof> = {
  encode(message: SignedMessageProof, writer: BinaryWriter = new BinaryWriter()): BinaryWriter {
    if (message.publicKeyHex !== "") {
      writer.uint32(10).string(message.publicKeyHex);
    }
    if (message.signatureHex !== "") {
      writer.uint32(18).string(message.signatureHex);
    }
    return writer;
  },

  decode(input: BinaryReader | Uint8Array, length?: number): SignedMessageProof {
    const reader = input instanceof BinaryReader ? input : new BinaryReader(input);
    const end = length === undefined ? reader.len : reader.pos + length;
    const message = createBaseSignedMessageProof();
    while (reader.pos < end) {
      const tag = reader.uint32();
      switch (tag >>> 3) {
        case 1: {
          if (tag !== 10) {
            break;
          }

          message.publicKeyHex = reader.string();
          continue;
        }
        case 2: {
          if (tag !== 18) {
            break;
          }

          message.signatureHex = reader.string();
          continue;
        }
      }
      if ((tag & 7) === 4 || tag === 0) {
        break;
      }
      reader.skip(tag & 7);
    }
    return message;
  },

  fromJSON(object: any): SignedMessageProof {
    return {
      publicKeyHex: isSet(object.publicKeyHex)
        ? globalThis.String(object.publicKeyHex)
        : isSet(object.public_key_hex)
        ? globalThis.String(object.public_key_hex)
        : "",
      signatureHex: isSet(object.signatureHex)
        ? globalThis.String(object.signatureHex)
        : isSet(object.signature_hex)
        ? globalThis.String(object.signature_hex)
        : "",
    };
  },

  toJSON(message: SignedMessageProof): unknown {
    const obj: any = {};
    if (message.publicKeyHex !== "") {
      obj.publicKeyHex = message.publicKeyHex;
    }
    if (message.signatureHex !== "") {
      obj.signatureHex = message.signatureHex;
    }
    return obj;
  },

  create<I extends Exact<DeepPartial<SignedMessageProof>, I>>(base?: I): SignedMessageProof {
    return SignedMessageProof.fromPartial(base ?? ({} as any));
  },
  fromPartial<I extends Exact<DeepPartial<SignedMessageProof>, I>>(object: I): SignedMessageProof {
    const message = createBaseSignedMessageProof();
    message.publicKeyHex = object.publicKeyHex ?? "";
    message.signatureHex = object.signatureHex ?? "";
    return message;
  },
};

